import urllib.request, urllib.parse, time
BASE = "http://160.202.254.160:15880/"
PROXY = {"http": "http://127.0.0.1:12001", "https": "http://127.0.0.1:12001"}
op = urllib.request.build_opener(urllib.request.ProxyHandler(PROXY))

def get():
    with op.open(BASE, timeout=20) as r:
        return r.read().decode("gb18030", "replace")

def post(content):
    data = urllib.parse.urlencode({"content": content}).encode()
    with op.open(BASE, data=data, timeout=20) as r:
        r.read()

chars = list("<>/\"'()_=&;#:[]{}$%*+-.,!?@~^|\\`") + ["\n", "\t", "\r"]
results = []
for ch in chars:
    mark = "M%02xMARK" % ord(ch)
    try:
        post(mark + ch + "END")
        time.sleep(0.06)
        body = get()
    except Exception as e:
        results.append((ch, "ERR", str(e)[:40])); continue
    i = body.find(mark)
    if i < 0:
        results.append((ch, "未找到", "")); continue
    seg = body[i+len(mark): i+len(mark)+10]
    results.append((ch, "原样" if seg.startswith(ch) else "转义", seg))

for ch, verdict, seg in results:
    print("  %-6r %-6s %r" % (ch, verdict, seg))
